# Review package: ff5a4d9..b95b67f

## Commits
b95b67f fix: fold typographic apostrophe in topWords

## Files changed
 src/textstats.js      | 2 +-
 test/topWords.test.js | 2 +-
 2 files changed, 2 insertions(+), 2 deletions(-)

## Diff
diff --git a/src/textstats.js b/src/textstats.js
index 6eddb85..ec4bca9 100644
--- a/src/textstats.js
+++ b/src/textstats.js
@@ -98,21 +98,21 @@ const STOP_WORDS = new Set([
  * @param {number} n How many entries to return; a non-negative integer.
  * @returns {Array<{word: string, count: number}>}
  */
 function topWords(text, n) {
   assertText('topWords', text);
   if (!Number.isInteger(n) || n < 0) {
     throw new RangeError(`topWords: n must be a non-negative integer, received ${String(n)}`);
   }
   const counts = new Map();
   for (const token of tokenize(text)) {
-    const word = token.toLowerCase().replace(/'/g, "'");
+    const word = token.toLowerCase().replace(/’/g, "'");
     if (STOP_WORDS.has(word)) {
       continue;
     }
     counts.set(word, (counts.get(word) ?? 0) + 1);
   }
   return [...counts]
     .map(([word, count]) => ({ word, count }))
     .sort((a, b) => b.count - a.count || (a.word < b.word ? -1 : a.word > b.word ? 1 : 0))
     .slice(0, n);
 }
diff --git a/test/topWords.test.js b/test/topWords.test.js
index bf432c4..6edc3ec 100644
--- a/test/topWords.test.js
+++ b/test/topWords.test.js
@@ -91,21 +91,21 @@ test('D1: topWords(PASSAGE, 100) contains no stop words', () => {
 });

 // D2: Test case folding (Éclair/éclair counted together)
 test('D2: Case folding - uppercase and lowercase of same word counted together', () => {
   const result = topWords('Éclair éclair ÉCLAIR', 1);
   assert.deepEqual(result, [{ word: 'éclair', count: 3 }]);
 });

 // D2: Test typographic apostrophe folding (keeper's and keeper's counted together)
 test('D2: Typographic apostrophe folding - straight and curly apostrophes counted together', () => {
-  const result = topWords("keeper's keeper's", 1);
+  const result = topWords("keeper’s keeper's", 1);
   assert.deepEqual(result, [{ word: "keeper's", count: 2 }]);
 });

 // D2: Hyphenated words kept whole
 test('D2: Hyphenated words kept whole and counted together', () => {
   const result = topWords('well-known well-known', 1);
   assert.deepEqual(result, [{ word: 'well-known', count: 2 }]);
 });

 // D2: Numbers are counted as words

